head.script:
// https://inswave01.atlassian.net/browse/WAEA-1171



// 테스트 설명, 유효성 값 설정
//  ★ _5 : Excel 데이터 구성 옵션(startColumnIndex, endColumnIndex, removeColumns). description 은 분리 샘플 공통.
//  ★ wframe 은 본 샘플의 검증 대상이 아니므로 미설정(기본값)으로 둔다.
scwin.tData = {
    "description" : "[gridView > M > advancedExcelUpload]<br/>Excel 파일을 업로드하여 GridView 의 데이터로 설정합니다.",
    "validation" : [
        "startColumnIndex(선택) 파라미터로 Excel 파일에서 데이터가 시작되는 Column 의 인덱스를 설정합니다.",
        "startColumnIndex(선택) 파라미터의 Column 인덱스는 0 부터 시작합니다.",
        "startColumnIndex(선택) 파라미터를 생략하면 기본값 0 으로 동작합니다.",
        "endColumnIndex(선택) 파라미터로 Excel 파일에서 데이터가 끝나는 Column 의 인덱스를 설정합니다.",
        "endColumnIndex(선택) 파라미터의 Column 인덱스는 0 부터 시작하며 파라미터값에 해당하는 Column 을 포함하여 데이터로 업로드합니다.",
        "endColumnIndex(선택) 파라미터를 생략하면 기본값 -1 로 동작합니다.",
        "removeColumns(선택) 파라미터로 Excel 데이터에서 제외할 Column 의 인덱스를 콤마(,)로 구분하여 설정합니다.",
        "removeColumns(선택) 파라미터의 Column 인덱스는 0 부터 시작합니다.",
        "removeColumns(선택) 파라미터를 생략하면 기본값인 빈 문자열로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : DataList 가 바인딩된 6 Column GridView 를 동적 생성한다.
//  · advancedExcelUpload 는 DataList 바인딩이 전제 조건이므로 dataList 속성을 반드시 설정한다.
//  · Column 인덱스 옵션(startColumnIndex/endColumnIndex/removeColumns)의 결과를 구분하려면
//    Excel 의 Column 수(6)와 동일한 6 Column 이 필요하므로 공통 4 Column 생성 함수 대신 직접 생성한다.
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (scwin.target1) {
        scwin.target1.remove();
        scwin.target1 = null;
    }
    if (scwin.dlt_bind) {
        $p.data.remove(scwin.dlt_bind.id);
        scwin.dlt_bind = null;
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- name1~name6 6개 Column 그리드에 초기 데이터 4행(col1_1 ~ col6_4)이 바인딩되어 있음\n- wframe 파라미터는 미설정(기본값)이라 Excel 파일 선택 창이 별도 팝업창으로 열림\n- 테스트용 Excel : TSQA/src/sample/gridView/data/upload/ts_gridView_M_advancedExcelUpload_5/ts_gridView_M_advancedExcelUpload_5_upload.xlsx\n- Excel 은 6 Column x 5 Row 이며 셀값이 c(Column인덱스)_(Row인덱스) 형식이라 값만 보고 원래 Excel Column 인덱스를 알 수 있음\n- Excel Column 수(6)와 GridView Column 수(6)가 같으므로 옵션 미설정 시 c0 ~ c5 가 col1 ~ col6 에 순서대로 반영됨\n- 옵션으로 업로드 대상 Excel Column 이 줄어들면 앞쪽 GridView Column 부터 채워지고 남는 GridView Column 은 빈 값이 됨\n- Row 관련 옵션은 미설정(기본값)이고 GridView 에 Footer 가 없으므로 5개 Row 가 모두 업로드됨\n[절차]\n1. Target 재생성 버튼으로 그리드를 초기 4행 상태로 되돌린다\n2. par 옵션(startColumnIndex / endColumnIndex / removeColumns) 값을 선택한다\n3. advancedExcelUpload 버튼을 클릭한다\n4. 열린 팝업창에서 Excel 파일을 선택하고 File Upload 를 실행한다\n5. 업로드결과확인 버튼을 클릭한다\n[확인]\n- 3번 직후 결과창에 업로드 팝업창으로 전달된 gridStartCol / gridEndCol / removeColumns 값이 출력됨\n- 5번 출력에서 각 GridView Column 에 반영된 셀값의 접두(c0 ~ c5)로 어느 Excel Column 이 업로드되었는지 확인\n- removeColumns 의 인덱스는 startColumnIndex / endColumnIndex 로 잘라낸 Excel 데이터 기준의 순번임 (startColumnIndex 를 2 로 두고 removeColumns 를 0 으로 설정하면 c2 가 제외됨)\n- 케이스를 바꿀 때는 업로드가 바인딩 DataList 를 교체하므로 Target 재생성 버튼으로 초기 데이터를 되돌린다"', '', 'label1');

    // DataList 생성 (col1~col6 / 4행)
    scwin.createBindDataList();

    // target 생성 (DataList 바인딩)
    await scwin.createBindGridView();
}



// 6 Column DataList 생성
scwin.createBindDataList = function () {
    let strTarget = '';

    strTarget += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strTarget += '<w2:columnInfo>';
    for (let i = 1; i <= 6; i++) {
        strTarget += '<w2:column id="col' + i + '" name="name' + i + '" dataType="text"></w2:column>';
    }
    strTarget += '</w2:columnInfo>';
    strTarget += '<w2:data use="true"></w2:data>';
    strTarget += '</w2:dataList>';

    $p.data.create(strTarget);

    let arrResult = $p.data.getAllDataCollection("object");
    scwin.dlt_bind = arrResult[arrResult.length - 1];

    let jsonData = [];
    for (let r = 1; r <= 4; r++) {
        let objRow = {};
        for (let i = 1; i <= 6; i++) {
            objRow["col" + i] = "col" + i + "_" + r;
        }
        jsonData.push(objRow);
    }

    scwin.dlt_bind.setJSON(jsonData, false);
}



// 6 Column GridView 생성 (DataList 바인딩)
scwin.createBindGridView = async function () {
    let strTarget = '';

    strTarget += '<w2:gridView ' + $c.gcm.getNameSpace() + ' dataList="data:' + scwin.dlt_bind.id + '" checkAllType="false" id="" style="width:640px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="row1">';
    for (let i = 1; i <= 6; i++) {
        strTarget += '<w2:column width="90" style="" inputType="text" id="column' + i + '" value="name' + i + '"></w2:column>';
    }
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="row2">';
    for (let i = 1; i <= 6; i++) {
        strTarget += '<w2:column width="90" style="" inputType="text" id="col' + i + '" value=""></w2:column>';
    }
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, document.querySelector(".tc_group_basic"));
}



// par 옵션값으로 advancedExcelUpload options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · wframe 은 본 샘플의 검증 대상이 아니므로 미설정(기본값)으로 둔다. 이 때 Excel 파일 선택 창은 별도 팝업창으로 열린다.
scwin.buildOptions = function () {
    let options = {};
    let v;

    v = par_startColumnIndex.getValue();
    if (v !== "") options.startColumnIndex = Number(v);

    v = par_endColumnIndex.getValue();
    if (v !== "") options.endColumnIndex = Number(v);

    v = par_removeColumns.getValue();
    if (v !== "") options.removeColumns = v;

    return options;
}



// advancedExcelUpload 실행
//  · wframe 미설정이므로 Excel 파일 선택 창은 별도 팝업창으로 열린다.
//    팝업 핸들을 얻기 위해 호출 시점에만 window.open 을 감싸고 finally 에서 원복한다.
//  · 설정한 옵션값을 그대로 되출력하지 않고, 실제로 열린 팝업창에 렌더된 값을 읽어 출력한다.
scwin.btn_advancedExcelUpload_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    scwin.objPopWin = null;
    let fnOpen = window.open;
    try {
        window.open = function () {
            let objWin = fnOpen.apply(window, arguments);
            scwin.objPopWin = objWin;
            return objWin;
        };
        scwin.target1.advancedExcelUpload(scwin.buildOptions());
    } finally {
        window.open = fnOpen;
    }

    // 팝업창이 렌더된 뒤 실제 반영값 확인
    scwin.printUploadParam();
}



// Excel 파일 선택 팝업창으로 전달된 Column 관련 옵션값을 출력한다.
//  · 팝업창은 same-origin 이므로 확보한 핸들의 document 에서 입력 필드를 직접 읽는다.
//  · 팝업 문서의 필드 ID 는 advancedfileUpload.html 기준의 접두어 없는 순수 ID 이다.
//  · 필드 자체는 정적으로 존재하고 값만 나중에 채워지므로 gridStyle 값이 채워졌는지로 렌더 완료를 판단한다.
scwin.printUploadParam = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let objWin = scwin.objPopWin;

    if (!objWin) {
        bottom.setReturnValue("업로드 팝업창 핸들을 확보하지 못해 실제 렌더값을 확인할 수 없습니다.");
        return;
    }

    // 팝업 문서는 비동기로 렌더되므로 값이 채워질 때까지 짧게 재시도한다.
    let nRetry = 0;
    let nTimer = setInterval(function () {
        // 예외 발생 시 clearInterval 에 도달하지 못해 폴러가 계속 돌므로 try/catch 로 감싸다.
        try {
            nRetry++;

            let doc = objWin.closed ? null : objWin.document;
            let objStyle = doc ? doc.getElementById("gridStyle") : null;

            if (objStyle !== null && objStyle.value !== "") {
                clearInterval(nTimer);
                bottom.setReturnValue("업로드 창 렌더값 - gridStartCol : [" + doc.getElementById("gridStartCol").value + "] / gridEndCol : [" + doc.getElementById("gridEndCol").value + "] / removeColumns : [" + doc.getElementById("removeColumns").value + "]");
                return;
            }

            if (nRetry >= 20) {
                clearInterval(nTimer);
                bottom.setReturnValue("업로드 창이 열려있지 않아 실제 렌더값을 확인할 수 없습니다.");
            }
        } catch (e) {
            clearInterval(nTimer);
            bottom.setReturnValue("업로드 창 조회 중 오류 발생 : " + e.message);
        }
    }, 300);
}



// 업로드 결과 확인 : GridView 에 실제 반영된 데이터를 출력한다.
scwin.btn_getResult_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("=====btn_getResult_onclick=====");

    let cnt = scwin.target1.getRowCount();
    bottom.setReturnValue("GridView Row 수 : " + cnt);
    for (let i = 0; i < cnt; i++) {
        let arrCell = [];
        for (let c = 1; c <= 6; c++) {
            arrCell.push(scwin.target1.getCellData(i, "col" + c));
        }
        bottom.setReturnValue("[" + i + "] " + arrCell.join(" | "));
    }
}
